#' Spatial Panel Regression
#'
#' 
#' @param data .
#' @param dep .
#' @param covs .
#' @param noLag .
#' @param timeVar .
#' @param idVar .
#' @param xVar .
#' @param yVar .
#' @param wSource .
#' @param wFile .
#' @param wIdField .
#' @param wMethod .
#' @param wK .
#' @param wDist .
#' @param wPower .
#' @param wCutoff .
#' @param wOrder .
#' @param wCumul .
#' @param wSymm .
#' @param wLonLat .
#' @param wStyle .
#' @param showGuide .
#' @param showHelp .
#' @param model .
#' @param panelEffects .
#' @param level .
#' @param showEffects .
#' @param nsim .
#' @param seed .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$coef} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$fit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$effectsTable} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$coef$asDF}
#'
#' \code{as.data.frame(results$coef)}
#'
#' @export
span <- function(
    data,
    dep,
    covs,
    noLag,
    timeVar,
    idVar,
    xVar,
    yVar,
    wSource = "coords",
    wFile = "",
    wIdField = "",
    wMethod = "auto",
    wK = 5,
    wDist = 0,
    wPower = 1,
    wCutoff = 0,
    wOrder = 1,
    wCumul = FALSE,
    wSymm = FALSE,
    wLonLat = FALSE,
    wStyle = "W",
    showGuide = FALSE,
    showHelp = FALSE,
    model = "sar",
    panelEffects = "individual",
    level = 95,
    showEffects = TRUE,
    nsim = 500,
    seed = 1) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("span requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(noLag)) noLag <- jmvcore::resolveQuo(jmvcore::enquo(noLag))
    if ( ! missing(timeVar)) timeVar <- jmvcore::resolveQuo(jmvcore::enquo(timeVar))
    if ( ! missing(idVar)) idVar <- jmvcore::resolveQuo(jmvcore::enquo(idVar))
    if ( ! missing(xVar)) xVar <- jmvcore::resolveQuo(jmvcore::enquo(xVar))
    if ( ! missing(yVar)) yVar <- jmvcore::resolveQuo(jmvcore::enquo(yVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(noLag), noLag, NULL),
            `if`( ! missing(timeVar), timeVar, NULL),
            `if`( ! missing(idVar), idVar, NULL),
            `if`( ! missing(xVar), xVar, NULL),
            `if`( ! missing(yVar), yVar, NULL))


    options <- spanOptions$new(
        dep = dep,
        covs = covs,
        noLag = noLag,
        timeVar = timeVar,
        idVar = idVar,
        xVar = xVar,
        yVar = yVar,
        wSource = wSource,
        wFile = wFile,
        wIdField = wIdField,
        wMethod = wMethod,
        wK = wK,
        wDist = wDist,
        wPower = wPower,
        wCutoff = wCutoff,
        wOrder = wOrder,
        wCumul = wCumul,
        wSymm = wSymm,
        wLonLat = wLonLat,
        wStyle = wStyle,
        showGuide = showGuide,
        showHelp = showHelp,
        model = model,
        panelEffects = panelEffects,
        level = level,
        showEffects = showEffects,
        nsim = nsim,
        seed = seed)

    analysis <- spanClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

